impl Solution{pub fn number_of_patterns(m:i32,n:i32)->i32{fn f(cur:usize,left:i32,skip:&[[usize;10];10],vis:&mut[bool;10])->i32{if left==0{return 1}vis[cur]=true;let mut r=0;for x in 1..=9{if !vis[x]&&(skip[cur][x]==0||vis[skip[cur][x]]){r+=f(x,left-1,skip,vis)}}vis[cur]=false;r}let mut skip=[[0usize;10];10];for &(a,b,c) in &[(1,3,2),(1,7,4),(3,9,6),(7,9,8),(1,9,5),(3,7,5),(4,6,5),(2,8,5)]{skip[a][b]=c;skip[b][a]=c;}let mut r=0;for l in m..=n{let mut v=[false;10];r+=4*f(1,l-1,&skip,&mut v)+4*f(2,l-1,&skip,&mut v)+f(5,l-1,&skip,&mut v);}r}}
